[CmdletBinding()]
param(
    [string]$ProjectRoot = ""
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$TargetFiles = @(
    "app\ui\shell.py",
    "app\ui\static\js\popup-bitrix-bridge.js",
    "app\ui\static\js\popup-init.js",
    "app\ui\templates\popup.html",
    "app\ui\static\js\popup-script-manifest.json"
)

function Test-ChecklistProjectRoot([string]$Path) {
    if ([string]::IsNullOrWhiteSpace($Path)) {
        return $false
    }
    return (
        (Test-Path -LiteralPath (Join-Path $Path "main.py") -PathType Leaf) -and
        (Test-Path -LiteralPath (Join-Path $Path "app\ui\shell.py") -PathType Leaf)
    )
}

function Resolve-ChecklistProjectRoot {
    $Candidates = @()
    if (-not [string]::IsNullOrWhiteSpace($ProjectRoot)) {
        $Candidates += $ProjectRoot
    }
    $Candidates += (Get-Location).Path
    if (-not [string]::IsNullOrWhiteSpace($PSScriptRoot)) {
        $Candidates += $PSScriptRoot
    }

    foreach ($Candidate in $Candidates) {
        try {
            $Resolved = (Resolve-Path -LiteralPath $Candidate -ErrorAction Stop).Path
            if (Test-ChecklistProjectRoot $Resolved) {
                return $Resolved
            }
        } catch {}
    }

    throw "Project root was not found. Run this installer from the bitrix-collab-checklist directory or pass -ProjectRoot."
}

function Resolve-PythonCommand([string]$Root) {
    $VenvPython = Join-Path $Root ".venv\Scripts\python.exe"
    if (Test-Path -LiteralPath $VenvPython -PathType Leaf) {
        return @($VenvPython)
    }
    if (Get-Command py -ErrorAction SilentlyContinue) {
        return @("py", "-3")
    }
    if (Get-Command python -ErrorAction SilentlyContinue) {
        return @("python")
    }
    throw "Python 3 was not found (.venv, py -3, or python)."
}

function Invoke-CheckedPython([string[]]$PythonCommand, [string[]]$Arguments) {
    $Executable = $PythonCommand[0]
    $PrefixArguments = @()
    if ($PythonCommand.Count -gt 1) {
        $PrefixArguments = $PythonCommand[1..($PythonCommand.Count - 1)]
    }
    & $Executable @PrefixArguments @Arguments
    if ($LASTEXITCODE -ne 0) {
        throw "Python command failed with exit code $LASTEXITCODE."
    }
}

$ResolvedProjectRoot = Resolve-ChecklistProjectRoot
$PythonCommand = Resolve-PythonCommand $ResolvedProjectRoot
$PatchWorkDir = Join-Path ([IO.Path]::GetTempPath()) ("checklist_popup_geometry_fix_" + [Guid]::NewGuid().ToString("N"))
$PatchScript = Join-Path $PatchWorkDir "apply_fix.py"
$BackupDir = Join-Path $PatchWorkDir "backup"
$LocationPushed = $false
$PayloadApplied = $false
$KeepPatchWorkDir = $false

try {
    New-Item -ItemType Directory -Path $PatchWorkDir -Force | Out-Null

    $PatchBytes = [Convert]::FromBase64String("")
    [IO.File]::WriteAllBytes($PatchScript, $PatchBytes)

    Push-Location $ResolvedProjectRoot
    $LocationPushed = $true

    Write-Host "Installing popup geometry fix 8.15.9.7..."
    Invoke-CheckedPython $PythonCommand @(
        $PatchScript,
        "apply",
        "--project", $ResolvedProjectRoot,
        "--backup", $BackupDir
    )
    $PayloadApplied = $true

    Invoke-CheckedPython $PythonCommand @(
        "-m", "py_compile",
        (Join-Path $ResolvedProjectRoot "app\ui\shell.py")
    )
    Write-Host "Python compile: OK"

    Invoke-CheckedPython $PythonCommand @(
        "-c",
        "from main import app; assert app is not None; print('FastAPI import: OK')"
    )

    $NodeCommand = Get-Command node -ErrorAction SilentlyContinue
    if ($null -ne $NodeCommand) {
        & $NodeCommand.Source --check (Join-Path $ResolvedProjectRoot "app\ui\static\js\popup-bitrix-bridge.js")
        if ($LASTEXITCODE -ne 0) { throw "Node syntax check failed for popup-bitrix-bridge.js." }
        & $NodeCommand.Source --check (Join-Path $ResolvedProjectRoot "app\ui\static\js\popup-init.js")
        if ($LASTEXITCODE -ne 0) { throw "Node syntax check failed for popup-init.js." }
        Write-Host "JavaScript syntax: OK"
    } else {
        Write-Host "JavaScript syntax: SKIPPED (Node.js is not installed)"
    }

    Invoke-CheckedPython $PythonCommand @(
        $PatchScript,
        "validate",
        "--project", $ResolvedProjectRoot,
        "--backup", $BackupDir
    )

    Write-Host ""
    Write-Host "Popup geometry fix 8.15.9.7 installed successfully." -ForegroundColor Green
    Write-Host "Changed files:"
    foreach ($TargetFile in $TargetFiles) {
        Write-Host ("  " + $TargetFile)
    }
    Write-Host ""
    Write-Host "Reload the Bitrix24 tab once, then test open -> close with X -> open three times without reloading."
}
catch {
    $OriginalError = $_
    if ($PayloadApplied -and (Test-Path -LiteralPath $BackupDir -PathType Container)) {
        try {
            Invoke-CheckedPython $PythonCommand @(
                $PatchScript,
                "restore",
                "--project", $ResolvedProjectRoot,
                "--backup", $BackupDir
            )
            Write-Host "Installation failed; original target files were restored." -ForegroundColor Yellow
        } catch {
            $KeepPatchWorkDir = $true
            Write-Host "WARNING: automatic restore failed. Backup remains at: $BackupDir" -ForegroundColor Red
        }
    }
    throw $OriginalError
}
finally {
    if ($LocationPushed) {
        Pop-Location
    }
    if ((-not $KeepPatchWorkDir) -and (Test-Path -LiteralPath $PatchWorkDir)) {
        Remove-Item -LiteralPath $PatchWorkDir -Recurse -Force -ErrorAction SilentlyContinue
    }
}
